import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { User } from 'src/app/shared/models/user.model';

@Injectable({
  providedIn: 'root'
})
export class AuthService {

  private readonly authTokenKey = 'authToken';
  private readonly userMailKey = 'userMail';
  private readonly userNameKey = 'userName';
  private readonly userIdKey = 'userId';

  private userMailSubject = new BehaviorSubject<string | null>(null);
  private userLoggedInSubject = new BehaviorSubject<boolean>(false);

  constructor() {
    this.userMailSubject.next(sessionStorage.getItem(this.userMailKey));
    this.userLoggedInSubject.next(sessionStorage.getItem(this.authTokenKey) !== null);
  }
  setUserSession(user: User, token: string) {
    this.setAuthToken(token);
    this.setUserMail(user.email);
    this.setUserName(user.name ? user.name : '');
  }

  setAuthToken(token: string) {
    sessionStorage.setItem(this.authTokenKey, token);
    this.userLoggedInSubject.next(true);
  }

  getAuthToken(): string | null {
    return sessionStorage.getItem(this.authTokenKey);
  }

  isLoggedInObservable(): Observable<boolean> {
    return this.userLoggedInSubject.asObservable();
  }

  setUserMail(userMail: string) {
    sessionStorage.setItem(this.userMailKey, userMail);
    this.userMailSubject.next(userMail);
  }

  getUserMail(): string | null {
    return sessionStorage.getItem(this.userMailKey);
  }

  getUserMailObservable() {
    return this.userMailSubject.asObservable();
  }

  setUserName(userName: string) {
    sessionStorage.setItem(this.userNameKey, userName);
  }

  getUserName(): string | null {
    return sessionStorage.getItem(this.userNameKey);
  }

  logOut() {
    sessionStorage.removeItem(this.authTokenKey);
    sessionStorage.removeItem(this.userMailKey);
    sessionStorage.removeItem(this.userNameKey);
    sessionStorage.removeItem(this.userIdKey);
    this.userMailSubject.next(null);
    this.userLoggedInSubject.next(false);
  }
}

import { Injectable } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { OmdbService } from 'src/app/shared/services/omdb/omdb.service';
import { MediaItemDialogComponent } from '../../components/movie-dialog/movie-dialog.component';
import { ToastrService } from 'ngx-toastr';
import { MediaItem } from '../../models/movie.model';
import { TrailerDialogComponent } from '../../components/trailer-dialog/trailer-dialog.component';
import { map, Observable, tap } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class DialogService {

  constructor(private OmdbService: OmdbService, private dialog: MatDialog, private toastrService: ToastrService) { }

openMediaItem(
  windowWidth: number, 
  mediaItem: MediaItem, 
  fromFavoritesSection: boolean
): Observable<void> {
  let dialogHeight = '90%';
  let dialogWidth = '80%';

  if (windowWidth > 600 && windowWidth < 800) {
    dialogHeight = '85%';
    dialogWidth = '70%';
  }
  if (windowWidth > 800) {
    dialogHeight = '85%';
    dialogWidth = '85%';
  }

  return this.OmdbService.getMediaItemInfo(mediaItem.imdbID).pipe(
    tap({
      next: (response) => {
        this.dialog.open(MediaItemDialogComponent, {
          data: {
            movie: mediaItem,
            response: response,
            fromFavoritesSection
          },
          height: dialogHeight,
          width: dialogWidth,
          panelClass: 'movie-details-dialog',
          enterAnimationDuration: '500ms',
          exitAnimationDuration: '500ms',
          autoFocus: false,
        });
      },
      error: (error) => {
        this.toastrService.error(error.message);
      }
    }),
    map(() => undefined)
  );
}


  openTrailerDialog(videoUrl: string) {
    this.dialog.open(TrailerDialogComponent, {
      data: {
        videoUrl: videoUrl,
      },
      width: '80vw',
      height: '70vh',
      maxWidth: '1200px',
      maxHeight: '800px',
      panelClass: 'trailer-dialog',
      autoFocus: false,
      disableClose: false,
      enterAnimationDuration: '300ms',
      exitAnimationDuration: '200ms',
    });
  }

}

import { HttpClient, HttpHeaders, HttpParams } from '@angular/common/http';
import { EventEmitter, Injectable } from '@angular/core';
import { MediaItem } from '../../models/movie.model';
import { environment } from 'src/environments/environment.development';
import { Observable } from 'rxjs';
import { AuthService } from 'src/app/core/services/auth.service';
import { DeleteResponse } from '../../models/deleteResponse.model';
import { FavoritesResponse } from '../../models/favoritesResponse.model';

@Injectable({
  providedIn: 'root',
})
export class FavoritesService {
  private baseUrl = environment.serverFavoritesURL;
  favoriteDeleted = new EventEmitter<string>();
  favoriteUpdated = new EventEmitter<MediaItem>();
  constructor(private http: HttpClient, private authService: AuthService) { }

  addToFavorites(movie: MediaItem): Observable<MediaItem> {
    const token = this.authService.getAuthToken();
    const options = {
      headers: new HttpHeaders({
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }),
    };
    return this.http.post<MediaItem>(this.baseUrl, movie, options)
  }

  getFavorites(
    currentPage: number,
    pageSize: number,
    sortField?: string,
    sortOrder?: number,
    searchTerm?: string,
    mediaType?: string,
  ): Observable<FavoritesResponse> {
    const token = this.authService.getAuthToken();
    let params = new HttpParams()
      .set('page', currentPage.toString())
      .set('pageSize', pageSize.toString());
    if (sortField) params = params.set('sortField', sortField);
    if (sortOrder) params = params.set('sortOrder', sortOrder.toString());
    if (mediaType && mediaType !== 'all') params = params.set('type', mediaType);
    if (searchTerm) params = params.set('searchTerm', searchTerm);

    const options = {
      headers: new HttpHeaders({
        'Authorization': `Bearer ${token}`
      }),
      params: params
    };

    return this.http.get<FavoritesResponse>(this.baseUrl, options);
  }
  deleteMediaItem(mediaId: string): Observable<DeleteResponse> {
    const token = this.authService.getAuthToken();
    const options = {
      headers: new HttpHeaders({
        'Authorization': `Bearer ${token}`
      })
    };
    return this.http.delete<DeleteResponse>(`${this.baseUrl}/${mediaId}`, options);
  }

  updateFavorite(mediaItem: MediaItem): Observable<MediaItem> {
    const token = this.authService.getAuthToken();
    const body = {
      description: mediaItem.description
    }
    const options = {
      headers: new HttpHeaders({
        'Content-Type': 'application/json',
         'Authorization': `Bearer ${token}`
      }),
    };
    return this.http.patch<MediaItem>(`${this.baseUrl}/${mediaItem._id}`, body, options)
  }
}

